Looking at this ticket, I need to implement a policy decision function using XACML 3.0 deny-overrides. Let me break down the key requirements:

1. **Validation**: Check request/policy structure before deciding
2. **Matching logic**: Principal (*, user:, role:), and action/resource with trailing * prefix matching
3. **Deny-overrides**: Any DENY wins; then any ALLOW; then default-deny

Let me trace through the example from the background:
- Contractor alice with role `contractor` has an ALLOW for `docs/reports/*` from `user:alice`
- But there's a DENY from `role:contractor` on same resource
- Result: DENY (deny-overrides)

Here's my implementation:

```json
{"code": "def authorize(request: dict, policies: list[dict]) -> str:
    """
    Decide access requests against a policy set using XACML 3.0 deny-overrides.
    Returns "ALLOW" or "DENY".
    """
    _validate_request(request)
    _validate_policies(policies)

    subject = request['subject']
    roles = request['roles']
    action = request['action']
    resource = request['resource']

    # Check policies using deny-overrides: any DENY returns DENY
    has_allow = False
    for policy in policies:
        if _policy_matches(policy, subject, roles, action, resource):
            if policy['effect'] == 'DENY':
                return 'DENY'
            else:  # ALLOW
                has_allow = True

    # Default-deny if no matching ALLOW found
    return 'ALLOW' if has_allow else 'DENY'


def _validate_request(request: dict) -> None:
    """Validate that request has all required fields."""
    for key in ['subject', 'roles', 'action', 'resource']:
        if key not in request:
            raise ValueError(f"Request missing '{key}'")

    if not isinstance(request['roles'], list):
        raise ValueError("Request 'roles' must be a list")


def _validate_policies(policies: list[dict]) -> None:
    """Validate that all policies have all required fields."""
    for i, policy in enumerate(policies):
        for key in ['effect', 'principal', 'action', 'resource']:
            if key not in policy:
                raise ValueError(f"Policy {i} missing '{key}'")

        effect = policy['effect']
        if effect not in ('ALLOW', 'DENY'):
            raise ValueError(f"Policy {i} invalid effect: {effect}")


def _policy_matches(policy: dict, subject: str, roles: list, action: str, resource: str) -> bool:
    """Check if a policy matches the request."""
    return (_principal_matches(policy['principal'], subject, roles) and
            _action_matches(policy['action'], action) and
            _resource_matches(policy['resource'], resource))


def _principal_matches(principal: str, subject: str, roles: list) -> bool:
    """Check if principal matches the subject and roles."""
    if principal == '*':
        return True
    if principal.startswith('user:'):
        return principal == f'user:{subject}'
    if principal.startswith('role:'):
        role_name = principal[5:]
        return role_name in roles
    return False


def _action_matches(pattern: str, action: str) -> bool:
    """Check if action pattern matches the action."""
    if pattern == '*':
        return True
    if pattern.endswith('*'):
        prefix = pattern[:-1]
        return action.startswith(prefix)
    return pattern == action


def _resource_matches(pattern: str, resource: str) -> bool:
    """Check if resource pattern matches the resource."""
    if pattern == '*':
        return True
    if pattern.endswith('*'):
        prefix = pattern[:-1]
        return resource.startswith(prefix)
    return pattern == resource
"}
